function estadoApiC5(d){
if(d.estado==="pendiente_autorizacion")return "pendiente";
if(d.estado==="autorizada")return "aceptada";
if(d.estado==="eliminada")return d.estado_notificacion==="rechazada"?"rechazada":"eliminada";
return d.estado||"desconocido";
}
// Envía al titular la solicitud de autorización de una obligación pendiente (código nuevo, SMS, correo y push)
async function solicitarAutorizacionC5(e,cu,d,t){
const neg=cu.Nombre_Empresa||"Un negocio";
const token=tokenSeguro();
await _upd(e,"Fac_deudas?id=eq."+d.id+"&estado=eq.pendiente_autorizacion",{token_autorizacion:await hashToken(token),celular_deudor:dig10(t.Celular)||null,email_deudor:t.email_contacto||null});
const url=urlPublica(e)+"/autorizar?token="+token,val=_pesos(d.Valor_total_deuda);
const r=await avisar(e,{empresa_id:cu.id,deuda_id:d.id,cuenta_destino:t.id,tipo:"obligacion",celular:t.Celular,email:t.email_contacto,
sms:"Plataforma C5: "+neg+" registro una obligacion a tu nombre por "+val+". Revisala y autoriza o rechaza aqui: "+url,
asunto:"Autorización requerida — "+neg,texto:neg+" registro una obligacion a tu nombre por "+val+" en Plataforma C5. Revisala y autoriza o rechaza aqui: "+url,
html:plantillaCorreo("Autorización requerida",["<strong>"+_escH(neg)+"</strong> registró una obligación a tu nombre por <strong style=\"color:#ff4d6d;\">"+val+"</strong>.","Para que quede registrada necesitamos tu autorización de tratamiento de datos (Ley 1581 de 2012). Si no la reconoces, puedes rechazarla en el mismo enlace."],{url,texto:"Revisar y responder"}),
push:pushDe("obligacion")});
await _ins(e,"Tbl_Mensajes",{empresa_id:cu.id,canal:"registro",estado:"enviado",referencia:"obl:"+d.id,deuda_id:d.id,cuenta_destino:t.id,tipo:"obligacion_registro"});
return r;
}
function _svc(e){return{"apikey":e.SUPABASE_SERVICE_KEY,"Authorization":"Bearer "+e.SUPABASE_SERVICE_KEY,"Content-Type":"application/json"};}
async function _get(e,path){try{const r=await fetch(e.SUPABASE_URL+"/rest/v1/"+path,{headers:_svc(e)});if(!r.ok)return [];const d=await r.json();return Array.isArray(d)?d:[];}catch(_){return [];}}
async function _uno(e,path){return (await _get(e,path))[0]||null;}
async function _ins(e,tabla,obj){try{const r=await fetch(e.SUPABASE_URL+"/rest/v1/"+tabla,{method:"POST",headers:{..._svc(e),"Prefer":"return=representation"},body:JSON.stringify(obj)});if(!r.ok)return null;const d=await r.json().catch(()=>[]);return Array.isArray(d)?(d[0]||null):d;}catch(_){return null;}}
async function _upd(e,path,obj){try{const r=await fetch(e.SUPABASE_URL+"/rest/v1/"+path,{method:"PATCH",headers:{..._svc(e),"Prefer":"return=representation"},body:JSON.stringify(obj)});if(!r.ok)return [];const d=await r.json().catch(()=>[]);return Array.isArray(d)?d:[];}catch(_){return [];}}
async function _del(e,path){try{await fetch(e.SUPABASE_URL+"/rest/v1/"+path,{method:"DELETE",headers:_svc(e)});}catch(_){}}
async function _rpc(e,fn,args){try{const r=await fetch(e.SUPABASE_URL+"/rest/v1/rpc/"+fn,{method:"POST",headers:_svc(e),body:JSON.stringify(args)});const t=await r.text();let d=null;try{d=JSON.parse(t);}catch(_){d=t;}return r.ok?{ok:true,data:d}:{ok:false,error:String((d&&d.message)||t||r.status)};}catch(ex){return{ok:false,error:ex.message};}}
function _J(o,s){return new Response(JSON.stringify(o),{status:s||200,headers:h()});}
function _escH(s){return String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function _pesos(n){return "$"+Math.round(Number(n)||0).toLocaleString("es-CO");}
function _dgDoc(s){return String(s||"").replace(/\D/g,"");}
function mismoDocumento(a,b){const x=_dgDoc(a),y=_dgDoc(b);return !!(x&&y&&(x===y||(x.length===y.length+1&&x.startsWith(y))||(y.length===x.length+1&&y.startsWith(x))));}
function textoLimpio(s,max){return String(s==null?"":s).replace(/[\u0000-\u001f\u007f<>]/g," ").replace(/\s+/g," ").trim().slice(0,max||300);}
function tieneEnlace(s){return /(https?:\/\/|www\.|\b[a-z0-9-]+\.(com|co|net|org|info|xyz|link|ly|me|io|app|site|online|top|click|shop)\b|\bbit\.ly\b)/i.test(String(s||""));}
function tokenSeguro(){const a=new Uint8Array(24);crypto.getRandomValues(a);return btoa(String.fromCharCode(...a)).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");}
async function hashToken(t){return "h:"+await sha256hex("tok|"+String(t||""));}
// Horario permitido para mensajes de cobro (Ley 2300 de 2023): lunes a viernes 7 a.m.–7 p.m., sábados 8 a.m.–3 p.m.
function horarioCobranza(d){const b=new Date((d||new Date()).getTime()-5*3600e3);const dia=b.getUTCDay(),hr=b.getUTCHours()+b.getUTCMinutes()/60;if(dia>=1&&dia<=5)return hr>=7&&hr<19;if(dia===6)return hr>=8&&hr<15;return false;}
async function cuentaDeSesion(e,tok,campos){const u=await usuarioDeSesion(e,tok);if(!u)return null;return await _uno(e,"Tbl_Cuenta?auth_user_id=eq."+u.id+"&select="+(campos||"id,Nombre_Empresa,Nro_documento,Celular,email_contacto,verificacion_estado,saldo_disponible"));}
async function valorConfig(e,clave,def){const c=await _uno(e,"Tbl_Configuracion?clave=eq."+encodeURIComponent(clave)+"&select=valor");const n=c?parseInt(c.valor):NaN;return isNaN(n)?def:n;}
// Titular (cuenta C5) de una obligación, a partir de la persona registrada
async function titularDeDeuda(e,deuda){
if(!deuda||!deuda.Id_persona)return null;
const p=await _uno(e,"Tbl_Persona?id=eq."+parseInt(deuda.Id_persona)+"&select=Nro_documento");
if(!p||!p.Nro_documento)return null;
return await _uno(e,"Tbl_Cuenta?Nro_documento=eq."+encodeURIComponent(p.Nro_documento)+"&select=id,Nombre_Empresa,Nro_documento,Celular,email_contacto");
}
async function esTitularDeDeuda(e,cuenta,deuda){if(!cuenta||!deuda||!deuda.Id_persona)return false;const p=await _uno(e,"Tbl_Persona?id=eq."+parseInt(deuda.Id_persona)+"&select=Nro_documento");return !!(p&&mismoDocumento(p.Nro_documento,cuenta.Nro_documento));}
// Correo con el diseño de C5. El texto llega ya escapado.
function plantillaCorreo(titulo,parrafos,boton,color){
return '<div style="font-family:Arial,sans-serif;max-width:520px;margin:0 auto;padding:28px;background:#111827;color:#e2e8f0;border-radius:12px;">'
+'<h2 style="color:'+(color||'#00ffcc')+';margin:0 0 16px;">'+titulo+'</h2>'
+parrafos.map(p=>'<p style="font-size:15px;line-height:1.7;margin:0 0 14px;">'+p+'</p>').join('')
+(boton?'<a href="'+boton.url+'" style="display:inline-block;background:linear-gradient(135deg,#00ffcc,#00b894);color:#001a14;padding:13px 26px;border-radius:10px;text-decoration:none;font-weight:700;font-size:15px;margin:6px 0;">'+boton.texto+'</a>':'')
+'<p style="color:#94a3b8;font-size:11px;margin-top:22px;border-top:1px solid rgba(255,255,255,.08);padding-top:14px;">Plataforma C5 · plataformac5.com · contacto@levatech.co</p></div>';
}
async function enviarSMSTexto(e,num10,texto){
if(!e.INFOBIP_BASE_URL||!e.INFOBIP_API_KEY||!num10)return{ok:false,error:"sin_config_o_numero"};
try{
const r=await fetch("https://"+e.INFOBIP_BASE_URL+"/sms/2/text/advanced",{method:"POST",headers:{"Authorization":"App "+e.INFOBIP_API_KEY,"Content-Type":"application/json"},body:JSON.stringify({messages:[{from:"PlataformaC5",destinations:[{to:"57"+num10}],text:String(texto).slice(0,480)}]})});
const d=await r.json().catch(()=>({}));const m=d.messages&&d.messages[0];const st=m&&m.status||{};
return r.ok&&m&&st.groupName!=="REJECTED"?{ok:true,id:m.messageId||null}:{ok:false,error:st.name||("http_"+r.status)};
}catch(ex){return{ok:false,error:ex.message};}
}
async function enviarCorreoTexto(e,email,asunto,texto,html){
if(!e.RESEND_API_KEY||!emailValido(email))return{ok:false,error:"sin_config_o_correo"};
try{
const r=await fetch("https://api.resend.com/emails",{method:"POST",headers:{"Authorization":"Bearer "+e.RESEND_API_KEY,"Content-Type":"application/json"},body:JSON.stringify({from:"Plataforma C5 <notificaciones@plataformac5.com>",reply_to:"contacto@levatech.co",to:[email],subject:String(asunto).slice(0,150),text:texto,html})});
const d=await r.json().catch(()=>({}));return r.ok?{ok:true,id:d.id||null}:{ok:false,error:d.message||("http_"+r.status)};
}catch(ex){return{ok:false,error:ex.message};}
}
// Envía por SMS y correo (y push si hay cuenta) y deja registro en Tbl_Mensajes
async function avisar(e,o){
// o: {empresa_id, deuda_id, cuenta_destino, tipo, celular, email, sms, asunto, texto, html, push:{title,body,url,tag}}
const res={sms:false,email:false,push:0};
const cel=dig10(o.celular);
if(o.sms&&cel){const r=await enviarSMSTexto(e,cel,o.sms);res.sms=r.ok;await _ins(e,"Tbl_Mensajes",{empresa_id:o.empresa_id||null,deuda_id:o.deuda_id||null,cuenta_destino:o.cuenta_destino||null,tipo:o.tipo,canal:"sms",estado:r.ok?"enviado":"error",proveedor_id:r.id||null,error:r.ok?null:_t(r.error,200)});}
if(o.html&&o.email&&emailValido(o.email)){const r=await enviarCorreoTexto(e,o.email,o.asunto,o.texto||o.sms||"",o.html);res.email=r.ok;await _ins(e,"Tbl_Mensajes",{empresa_id:o.empresa_id||null,deuda_id:o.deuda_id||null,cuenta_destino:o.cuenta_destino||null,tipo:o.tipo,canal:"email",estado:r.ok?"enviado":"error",proveedor_id:r.id||null,error:r.ok?null:_t(r.error,200)});}
if(o.push&&o.cuenta_destino)res.push=await pushACuenta(e,o.cuenta_destino,o.push);
return res;
}
// Cobro atómico de saldo (o del cupo de SMS del plan). Devuelve {ok, saldo, gratis} o {ok:false, error, costo, saldo}
async function cobrarSaldo(e,cuentaId,costo,tipo,descripcion,usaCupoSms){
if(usaCupoSms){const r=await _rpc(e,"c5_usar_cupo_sms",{p_cuenta:cuentaId});if(r.ok&&r.data===true)return{ok:true,gratis:true};}
if(!(costo>0))return{ok:true,gratis:true};
const r=await _rpc(e,"c5_mover_saldo",{p_cuenta:cuentaId,p_valor:-costo,p_tipo:tipo,p_desc:String(descripcion||"").slice(0,200)});
if(r.ok)return{ok:true,saldo:Number(r.data)};
if(/SALDO_INSUFICIENTE/.test(r.error)){const c=await _uno(e,"Tbl_Cuenta?id=eq."+cuentaId+"&select=saldo_disponible");return{ok:false,error:"saldo_insuficiente",costo,saldo:Number(c&&c.saldo_disponible||0)};}
return{ok:false,error:"cobro_fallido"};
}
async function devolverSaldo(e,cuentaId,costo,descripcion){if(costo>0)await _rpc(e,"c5_mover_saldo",{p_cuenta:cuentaId,p_valor:costo,p_tipo:"reintegro",p_desc:String(descripcion||"Reintegro").slice(0,200)});}

// ═════════ Notificaciones push (Web Push, RFC 8291 + VAPID RFC 8292) ═════════
function _b64u(buf){const b=buf instanceof Uint8Array?buf:new Uint8Array(buf);let s="";for(let k=0;k<b.length;k++)s+=String.fromCharCode(b[k]);return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");}
function _b64uDec(s){s=String(s||"").replace(/-/g,"+").replace(/_/g,"/");while(s.length%4)s+="=";const bin=atob(s);const out=new Uint8Array(bin.length);for(let k=0;k<bin.length;k++)out[k]=bin.charCodeAt(k);return out;}
function _cat(...arrs){const n=arrs.reduce((a,x)=>a+x.length,0);const o=new Uint8Array(n);let p=0;for(const x of arrs){o.set(x,p);p+=x.length;}return o;}
const _te=new TextEncoder();
async function _hmac(key,data){const k=await crypto.subtle.importKey("raw",key,{name:"HMAC",hash:"SHA-256"},false,["sign"]);return new Uint8Array(await crypto.subtle.sign("HMAC",k,data));}
async function cifrarPush(p256dh,authSecret,payload,fijo){
const uaPub=_b64uDec(p256dh),auth=_b64uDec(authSecret);
let asKeys,asPub,salt;
if(fijo){asKeys={privateKey:await crypto.subtle.importKey("jwk",fijo.jwk,{name:"ECDH",namedCurve:"P-256"},false,["deriveBits"])};asPub=_b64uDec(fijo.pub);salt=_b64uDec(fijo.salt);}
else{asKeys=await crypto.subtle.generateKey({name:"ECDH",namedCurve:"P-256"},true,["deriveBits"]);asPub=new Uint8Array(await crypto.subtle.exportKey("raw",asKeys.publicKey));salt=new Uint8Array(16);crypto.getRandomValues(salt);}
const uaKey=await crypto.subtle.importKey("raw",uaPub,{name:"ECDH",namedCurve:"P-256"},false,[]);
const shared=new Uint8Array(await crypto.subtle.deriveBits({name:"ECDH",public:uaKey},asKeys.privateKey,256));
const prkKey=await _hmac(auth,shared);
const ikm=(await _hmac(prkKey,_cat(_te.encode("WebPush: info\0"),uaPub,asPub,new Uint8Array([1])))).slice(0,32);
const prk=await _hmac(salt,ikm);
const cek=(await _hmac(prk,_cat(_te.encode("Content-Encoding: aes128gcm\0"),new Uint8Array([1])))).slice(0,16);
const nonce=(await _hmac(prk,_cat(_te.encode("Content-Encoding: nonce\0"),new Uint8Array([1])))).slice(0,12);
const k=await crypto.subtle.importKey("raw",cek,{name:"AES-GCM"},false,["encrypt"]);
const ct=new Uint8Array(await crypto.subtle.encrypt({name:"AES-GCM",iv:nonce},k,_cat(typeof payload==="string"?_te.encode(payload):payload,new Uint8Array([2]))));
const rs=new Uint8Array([0,0,16,0]);
return _cat(salt,rs,new Uint8Array([asPub.length]),asPub,ct);
}
async function jwtVapid(e,aud){
const pub=_b64uDec(e.VAPID_PUBLIC_KEY);
const jwk={kty:"EC",crv:"P-256",d:e.VAPID_PRIVATE_KEY,x:_b64u(pub.slice(1,33)),y:_b64u(pub.slice(33,65)),ext:true};
const key=await crypto.subtle.importKey("jwk",jwk,{name:"ECDSA",namedCurve:"P-256"},false,["sign"]);
const enc=o=>_b64u(_te.encode(JSON.stringify(o)));
const datos=enc({typ:"JWT",alg:"ES256"})+"."+enc({aud,exp:Math.floor(Date.now()/1000)+12*3600,sub:"mailto:contacto@levatech.co"});
const firma=new Uint8Array(await crypto.subtle.sign({name:"ECDSA",hash:"SHA-256"},key,_te.encode(datos)));
return datos+"."+_b64u(firma);
}
async function enviarPush(e,sub,msg){
try{
const url=new URL(sub.endpoint);
const cuerpo=await cifrarPush(sub.p256dh,sub.auth,JSON.stringify({title:msg.title||"Plataforma C5",body:msg.body||"",url:msg.url||"/",tag:msg.tag||"c5"}));
const r=await fetch(sub.endpoint,{method:"POST",headers:{"TTL":"86400","Urgency":"normal","Content-Encoding":"aes128gcm","Content-Type":"application/octet-stream","Authorization":"vapid t="+await jwtVapid(e,url.protocol+"//"+url.host)+", k="+e.VAPID_PUBLIC_KEY},body:cuerpo});
return r.status;
}catch(_){return 0;}
}
async function pushACuenta(e,cuentaId,msg){
if(!e.VAPID_PUBLIC_KEY||!e.VAPID_PRIVATE_KEY||!cuentaId)return 0;
const subs=await _get(e,"Tbl_Push_Suscripciones?cuenta_id=eq."+parseInt(cuentaId)+"&select=id,endpoint,p256dh,auth,fallos&limit=10");
let ok=0;
for(const s of subs){
const st=await enviarPush(e,s,msg);
if(st>=200&&st<300){ok++;await _upd(e,"Tbl_Push_Suscripciones?id=eq."+s.id,{ultimo_envio:new Date().toISOString(),fallos:0});}
else if(st===404||st===410)await _del(e,"Tbl_Push_Suscripciones?id=eq."+s.id);
else await _upd(e,"Tbl_Push_Suscripciones?id=eq."+s.id,{fallos:(s.fallos||0)+1});
}
return ok;
}
