// ── CRON JOB — NOTIFICACIONES PROGRAMADAS ──
async function ejecutarNotificacionesProgramadas(env) {
const S = env.SUPABASE_URL;
const K = env.SUPABASE_SERVICE_KEY;
const hoy = new Date().toISOString().slice(0,10);
const r = await fetch(S+'/rest/v1/Tbl_Notificaciones_Programadas?estado=eq.pendiente&fecha_programada=lte.'+hoy+'&select=*',{
headers:{'apikey':K,'Authorization':'Bearer '+K}
});
const notifs = await r.json();
if (!Array.isArray(notifs) || notifs.length === 0) return;
for (const n of notifs) {
const dr = await fetch(S+'/rest/v1/Fac_deudas?id=eq.'+n.deuda_id+'&select=estado,celular_deudor,email_deudor,Valor_total_deuda,nombre_empresa',{
headers:{'apikey':K,'Authorization':'Bearer '+K}
});
const deudas = await dr.json();
const deuda = deudas && deudas[0];
if (!deuda || deuda.estado === 'eliminada') {
await fetch(S+'/rest/v1/Tbl_Notificaciones_Programadas?id=eq.'+n.id,{
method:'PATCH',headers:{'apikey':K,'Authorization':'Bearer '+K,'Content-Type':'application/json','Prefer':'return=minimal'},
body:JSON.stringify({estado:'cancelada'})
});
continue;
}
const valor = '$'+parseFloat(deuda.Valor_total_deuda).toLocaleString('es-CO',{maximumFractionDigits:0});
const empresa = deuda.nombre_empresa || 'el negocio';
let msg = '';
if (n.tipo === 'vencimiento') msg = 'Plataforma C5: Tu obligacion de '+valor+' con '+empresa+' vence hoy. Contactalos para evitar mora.';
else if (n.tipo === 'preaviso') msg = 'Plataforma C5: AVISO. Tu obligacion de '+valor+' con '+empresa+' sera reportada en mora pronto. Contactalos ya.';
else msg = 'Plataforma C5: Recordatorio. Tu obligacion de '+valor+' con '+empresa+' vence en '+n.dias_antes+' dias.';
let enviado = false;
if (deuda.email_deudor) {
const asunto = n.tipo === 'preaviso' ? 'Aviso de mora — Plataforma C5' : 'Recordatorio de tu obligación — Plataforma C5';
const htmlBody = '<div style="font-family:Arial,sans-serif;max-width:520px;padding:28px;background:#111827;color:#e2e8f0;border-radius:12px;">'
+'<h2 style="color:#00ffcc;">Plataforma C5</h2>'
+'<p style="font-size:15px;line-height:1.7;">'+msg+'</p>'
+'<a href="https://plataformac5.com" style="display:inline-block;background:linear-gradient(135deg,#00ffcc,#00b894);color:#001a14;padding:12px 24px;border-radius:8px;text-decoration:none;font-weight:600;margin-top:16px;">Ver mis obligaciones</a>'
+'</div>';
const er = await fetch('https://api.resend.com/emails',{
method:'POST',headers:{'Authorization':'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json'},
body:JSON.stringify({from:'Plataforma C5 <notificaciones@plataformac5.com>',to:[deuda.email_deudor],subject:asunto,html:htmlBody})
});
enviado = er.ok;
}
if (!enviado && deuda.celular_deudor) {
const n2 = '57'+deuda.celular_deudor.replace(/\D/g,'').slice(-10);
await fetch('https://'+env.INFOBIP_BASE_URL+'/sms/2/text/advanced',{
method:'POST',headers:{'Authorization':'App '+env.INFOBIP_API_KEY,'Content-Type':'application/json'},
body:JSON.stringify({messages:[{from:'PlataformaC5',destinations:[{to:n2}],text:msg}]})
});
enviado = true;
}
await fetch(S+'/rest/v1/Tbl_Notificaciones_Programadas?id=eq.'+n.id,{
method:'PATCH',headers:{'apikey':K,'Authorization':'Bearer '+K,'Content-Type':'application/json','Prefer':'return=minimal'},
body:JSON.stringify({estado: enviado ? 'enviada' : 'fallida', fecha_enviada: new Date().toISOString(), mensaje_enviado: msg})
});
}
}
  


// ── CRON: AUTO-ACEPTACIÓN A 24H (silencio = aceptado) ──
// Revisa obligaciones/cuentas notificadas hace más de 24h sin respuesta del titular.
// Si nadie respondió, se confirma automáticamente. Solo se notifica al negocio si hubo
// una acción real (nunca por el silencio, que es el caso normal).
async function procesarAutoAceptacion(env) {
const S = env.SUPABASE_URL;
const K = env.SUPABASE_SERVICE_KEY;
const limite = new Date(Date.now() - 24*60*60*1000).toISOString();
const r = await fetch(S+'/rest/v1/Fac_deudas?estado_notificacion=eq.notificada&fecha_notificacion=lte.'+limite+'&select=id,estado,nombre_empresa', {
headers: { 'apikey': K, 'Authorization': 'Bearer '+K }
});
const pendientes = await r.json();
if (!Array.isArray(pendientes) || pendientes.length === 0) return;
for (const d of pendientes) {
// Silencio de 24h -> se confirma automáticamente. No se cambia el estado de la deuda
// (ya estaba autorizada/en curso); solo se marca la notificación como auto-confirmada.
await fetch(S+'/rest/v1/Fac_deudas?id=eq.'+d.id, {
method: 'PATCH',
headers: { 'apikey': K, 'Authorization': 'Bearer '+K, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
body: JSON.stringify({ estado_notificacion: 'auto_aceptada' })
});
// No se notifica al negocio en el caso de silencio: es el flujo normal, ya lo ve en su panel.
}
// Barrido de CARGOS (cuenta abierta) con la misma ventana de 24h
const rc = await fetch(S+'/rest/v1/Tbl_Abonos?es_cargo=eq.true&estado_notificacion=eq.notificada&fecha_notificacion=lte.'+limite+'&select=id', {
headers: { 'apikey': K, 'Authorization': 'Bearer '+K }
});
const cargosPend = await rc.json();
if (Array.isArray(cargosPend) && cargosPend.length > 0) {
for (const c of cargosPend) {
await fetch(S+'/rest/v1/Tbl_Abonos?id=eq.'+c.id, {
method: 'PATCH',
headers: { 'apikey': K, 'Authorization': 'Bearer '+K, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
body: JSON.stringify({ estado_notificacion: 'auto_aceptada' })
});
}
}
}

// ── CRON: GENERAR SIGUIENTE CUOTA DE OBLIGACIONES RECURRENTES ──
// Para cada obligación recurrente activa cuya fecha de vencimiento ya pasó (o es hoy),
// genera la siguiente cuota del mismo valor, notifica al titular, y continúa aunque
// la cuota anterior siga en mora (el contrato sigue generando sus ciclos).
async function generarCuotasRecurrentes(env) {
const S = env.SUPABASE_URL;
const K = env.SUPABASE_SERVICE_KEY;
const hoy = new Date().toISOString().slice(0,10);
const r = await fetch(S+'/rest/v1/Fac_deudas?tipo_obligacion=eq.recurrente&recurrencia_activa=eq.true&estado=in.(autorizada,en_mora)&Fecha_Vencimiento_deuda=lte.'+hoy+'&select=*', {
headers: { 'apikey': K, 'Authorization': 'Bearer '+K }
});
const cuotas = await r.json();
if (!Array.isArray(cuotas) || cuotas.length === 0) return;
for (const d of cuotas) {
// ¿Ya se generó la siguiente cuota para esta? (evitar duplicados si el cron corre más de una vez)
const chk = await fetch(S+'/rest/v1/Fac_deudas?id=eq.'+d.id+'&select=siguiente_generada', { headers: { 'apikey': K, 'Authorization': 'Bearer '+K } });
const chkData = await chk.json();
if (chkData && chkData[0] && chkData[0].siguiente_generada) continue;
// Calcular la siguiente fecha según frecuencia
var fv = new Date(d.Fecha_Vencimiento_deuda + 'T00:00:00');
var frecuencia = d.frecuencia_recurrencia || 'mensual';
if (frecuencia === 'mensual') fv.setMonth(fv.getMonth()+1);
else if (frecuencia === 'quincenal') fv.setDate(fv.getDate()+15);
else if (frecuencia === 'semanal') fv.setDate(fv.getDate()+7);
else if (frecuencia === 'diario') fv.setDate(fv.getDate()+1);
var siguienteFecha = fv.toISOString().slice(0,10);
var fechaFin = d.fecha_fin_recurrencia;
// Si la siguiente cuota ya pasa la fecha de fin del contrato, no se genera y se desactiva la serie
if (fechaFin && siguienteFecha > fechaFin) {
await fetch(S+'/rest/v1/Fac_deudas?id=eq.'+d.id, {
method: 'PATCH', headers: { 'apikey': K, 'Authorization': 'Bearer '+K, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
body: JSON.stringify({ recurrencia_activa: false, siguiente_generada: true })
});
continue;
}
// Token propio para la nueva cuota
var token = await hashToken(tokenSeguro());
const ins = await fetch(S+'/rest/v1/Fac_deudas', {
method: 'POST',
headers: { 'apikey': K, 'Authorization': 'Bearer '+K, 'Content-Type': 'application/json', 'Prefer': 'return=representation' },
body: JSON.stringify({
Id_persona: d.Id_persona, Id_empresa: d.Id_empresa, Valor_total_deuda: d.Valor_total_deuda,
Fecha_Vencimiento_deuda: siguienteFecha, Observacion: d.Observacion, celular_deudor: d.celular_deudor,
email_deudor: d.email_deudor, tipo_comercio_id: d.tipo_comercio_id, declaracion_aceptada: true,
nombre_empresa: d.nombre_empresa, estado: 'autorizada', token_autorizacion: token,
tipo_obligacion: 'recurrente', frecuencia_recurrencia: frecuencia, fecha_fin_recurrencia: fechaFin,
recurrencia_activa: true, estado_notificacion: 'notificada', fecha_notificacion: new Date().toISOString(),
deuda_origen_id: d.deuda_origen_id || d.id
})
});
const nueva = await ins.json();
try { const tC = await titularDeDeuda(env, d); if (tC) await pushACuenta(env, tC.id, pushDe("cuota")); } catch(_) {}
// Marcar la cuota anterior como que ya generó su siguiente (evita duplicados)
await fetch(S+'/rest/v1/Fac_deudas?id=eq.'+d.id, {
method: 'PATCH', headers: { 'apikey': K, 'Authorization': 'Bearer '+K, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
body: JSON.stringify({ siguiente_generada: true })
});
// Notificar al titular de la nueva cuota (con ventana de 24h)
var valorFmt = '$' + parseFloat(d.Valor_total_deuda).toLocaleString('es-CO', { maximumFractionDigits: 0 });
var msg = 'Plataforma C5: se generó tu cuota de ' + valorFmt + ' con ' + (d.nombre_empresa||'un negocio') + ', vence el ' + siguienteFecha + '. Tienes 24h para rechazarla desde tu panel; si no respondes, quedará confirmada.';
if (d.email_deudor) {
var htmlBody = '<div style="font-family:Arial,sans-serif;max-width:520px;padding:28px;background:#111827;color:#e2e8f0;border-radius:12px;"><h2 style="color:#00ffcc;">Plataforma C5</h2><p style="font-size:15px;line-height:1.7;">' + msg + '</p></div>';
await fetch('https://api.resend.com/emails', {
method: 'POST', headers: { 'Authorization': 'Bearer ' + env.RESEND_API_KEY, 'Content-Type': 'application/json' },
body: JSON.stringify({ from: 'Plataforma C5 <notificaciones@plataformac5.com>', to: [d.email_deudor], subject: 'Nueva cuota generada — ' + (d.nombre_empresa||'C5'), html: htmlBody })
});
} else if (d.celular_deudor) {
var n2 = '57' + d.celular_deudor.replace(/\D/g,'').slice(-10);
await fetch('https://' + env.INFOBIP_BASE_URL + '/sms/2/text/advanced', {
method: 'POST', headers: { 'Authorization': 'App ' + env.INFOBIP_API_KEY, 'Content-Type': 'application/json' },
body: JSON.stringify({ messages: [{ from: 'PlataformaC5', destinations: [{ to: n2 }], text: msg }] })
});
}
}
}

// ── CRON v7: AVISOS PUSH DE VENCIMIENTO (3 días antes y el día) ──
// Solo dentro del horario permitido para mensajes de cobro; cada aviso se envía una sola vez.
async function recordatoriosPush(env){
if(!env.VAPID_PUBLIC_KEY||!env.VAPID_PRIVATE_KEY||!horarioCobranza())return;
const bog=new Date(Date.now()-5*3600e3);
const d0=bog.toISOString().slice(0,10),d3=new Date(bog.getTime()+3*864e5).toISOString().slice(0,10);
const deudas=await _get(env,"Fac_deudas?estado=in.(autorizada,en_mora)&Fecha_Vencimiento_deuda=in.("+d0+","+d3+")&select=id,Id_persona,Fecha_Vencimiento_deuda,saldo_actual,Valor_total_deuda&limit=300");
const vivas=deudas.filter(d=>parseFloat(d.saldo_actual!=null?d.saldo_actual:d.Valor_total_deuda)>0);
if(!vivas.length)return;
const pids=[...new Set(vivas.map(d=>d.Id_persona).filter(Boolean))];
const ps=pids.length?await _get(env,"Tbl_Persona?id=in.("+pids.join(",")+")&select=id,Nro_documento"):[];
const docs=[...new Set(ps.map(x=>x.Nro_documento).filter(Boolean))];
const cs=docs.length?await _get(env,"Tbl_Cuenta?Nro_documento=in.("+docs.map(x=>'"'+String(x).replace(/"/g,"")+'"').join(",")+")&select=id,Nro_documento"):[];
const subs=cs.length?await _get(env,"Tbl_Push_Suscripciones?cuenta_id=in.("+cs.map(c=>c.id).join(",")+")&select=cuenta_id"):[];
const conPush=new Set(subs.map(s=>String(s.cuenta_id)));
const docPorPersona={};ps.forEach(x=>docPorPersona[x.id]=x.Nro_documento);
const cuentaPorDoc={};cs.forEach(c=>cuentaPorDoc[c.Nro_documento]=c.id);
for(const d of vivas){
const cid=cuentaPorDoc[docPorPersona[d.Id_persona]];
if(!cid||!conPush.has(String(cid)))continue;
const tipo=d.Fecha_Vencimiento_deuda===d0?"vencehoy":"vence3";
const r=await fetch(env.SUPABASE_URL+"/rest/v1/Tbl_Recordatorios_Push",{method:"POST",headers:{..._svc(env),"Prefer":"resolution=ignore-duplicates,return=representation"},body:JSON.stringify({deuda_id:d.id,tipo,fecha:d0})});
const ins=r.ok?await r.json().catch(()=>[]):[];
if(Array.isArray(ins)&&ins.length)await pushACuenta(env,cid,pushDe(tipo));
}
}
